import re

_PATTERN = re.compile(r"\s*(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?\s*")

_MULTIPLIERS = {
    "d": 24 * 60 * 60,
    "h": 60 * 60,
    "m": 60,
    "s": 1,
}


def parse_duration(s):
    match = _PATTERN.fullmatch(s)
    if match is None:
        raise ValueError("invalid duration: %r" % (s,))
    groups = match.groups()
    if all(g is None for g in groups):
        raise ValueError("invalid duration: %r" % (s,))
    total = 0
    for unit, amount in zip("dhms", groups):
        if amount is not None:
            total += int(amount) * _MULTIPLIERS[unit]
    return total
